"""Upgrade the catalogue format generated by older installers."""
import json
import subprocess
import sys
import tempfile
import unittest
from pathlib import Path

from ai_router.catalogue import check, merge
from tests import test_catalogue


class CatalogueUpgradeTests(unittest.TestCase):
    def test_merge_replaces_retired_rows_in_a_stale_roster(self):
        stale = {'models': [{'slug': 'gpt-5.6-sol'}, {'slug': 'gpt-5.6-luna'}]}
        merged = merge(stale, roster=('custom', 'gpt-5.6-sol', 'gpt-5.6-luna'))
        rows = {m['slug'] for m in merged['models']}
        self.assertTrue({'gpt-6-sol', 'gpt-6-luna'} <= rows)
        self.assertFalse({'gpt-5.6-sol', 'gpt-5.6-luna'} & rows)

    def test_cli_repairs_existing_stubs_and_preserves_metadata(self):
        with tempfile.TemporaryDirectory() as tmp:
            home = Path(tmp)
            roster = ['gpt-6-astra', 'gpt-6-luna']
            (home / 'mixed-router-state.json').write_text(
                json.dumps({'openai_models': roster}))
            path = home / 'mixed-models.json'
            path.write_text(json.dumps({'models': [
                {'slug': roster[0]},
                {'slug': roster[1], 'display_name': 'Custom label',
                 'context_window': 1000000,
                 'supported_reasoning_levels': [{'effort': 'high', 'description': 'Native'}],
                 'model_messages': {'instructions_template': 'Native instructions'}}]}))
            proc = subprocess.run(
                [sys.executable, '-m', 'ai_router.catalogue', '--merge', str(path)],
                capture_output=True, text=True)
            self.assertEqual(proc.returncode, 0, proc.stderr)
            catalog = json.loads(path.read_text())
            rows = {row['slug']: row for row in catalog['models']}
            for slug in roster:
                required = test_catalogue.CatalogueSchemaCompatTests.REQUIRED_FIELDS
                self.assertTrue(set(required) <= rows[slug].keys())
            self.assertEqual(rows[roster[0]]['display_name'], 'GPT-6-Astra')
            self.assertEqual(rows[roster[1]]['display_name'], 'Custom label')
            self.assertEqual(rows[roster[1]]['context_window'], 1000000)
            self.assertEqual(rows[roster[1]]['supported_reasoning_levels'][0]['effort'], 'high')
            self.assertEqual(rows[roster[1]]['model_messages']['instructions_template'],
                             'Native instructions')
            self.assertEqual(merge(json.loads(path.read_text()), roster), catalog)
            self.assertTrue(check(path))

    def test_check_rejects_incomplete_subscription_rows(self):
        with tempfile.TemporaryDirectory() as tmp:
            path = Path(tmp) / 'mixed-models.json'
            catalog = merge({'models': []})
            catalog['models'].append({'slug': 'gpt-6-astra'})
            path.write_text(json.dumps(catalog))
            self.assertFalse(check(path))


if __name__ == '__main__':
    unittest.main()
